"    private static void validateMockLoginRequest(MockLoginRequest request) {
        if (request == null || !request.unknownFields().isEmpty()) {
            throw ContractProblemException.validationError(
                    "Request payload contains undeclared or invalid properties.");
        }
        String email = request.getWorkspaceEmail();
        String displayName = request.getDisplayName();
        if (email == null || email.length() < 5 || email.length() > 255 || !EMAIL_PATTERN.matcher(email).matches()
                || displayName == null || displayName.isBlank() || displayName.length() > 255) {
            throw ContractProblemException.validationError(
                    "Valid workspaceEmail and non-blank displayName are required.");
        }
        validateMockRoleCodes(request.getRoleCodes());
    }
    private static void validateMockRoleCodes(List<String> roleCodes) {
        if (roleCodes == null) {
            return;
        }
        if (roleCodes.size() > 10) {
            throw ContractProblemException.validationError("roleCodes cannot exceed 10 items.");
        }
        for (String code : roleCodes) {
            if (code == null || code.length() < 2 || code.length() > 64) {
                throw ContractProblemException.validationError("Invalid roleCode length.");
            }
        }
    }"
